        fail(EXIT_OVERLOAD, "OVERLOAD")
    digest = hashlib.sha256(encoded).hexdigest()
    results.append(
        {
            "op": "se",
            "version": CHECKPOINT_VERSION,
            "digest": digest,
            "state": state,
