    candidate_state = export_bundle(candidate)
    candidate_bytes = json.dumps(
        candidate_state, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    if candidate_bytes != after_bytes:
        fail(EXIT_STATE, "STATE")
    # —— 阶段二：按 se 规则取得当前状态的规范化内存快照 ——
